export function recommendLogicTrack(score){return score<=1?'explorer':score===2?'strategist':'architect'}
export function logicChoiceIndex(seed,count){let hash=0;for(const char of seed)hash=(hash*31+char.charCodeAt(0))>>>0;return hash%count}
export function freshLogicChoiceIndex(trackId,kind,challenge,count){const base=logicChoiceIndex(`${trackId}:logic:${kind}`,count);return challenge?(base+1)%count:base}
